.control
* 1. DC Operating Point
op
let i_supply = -i(VDD)
let p_diss = i_supply * 1.8
let v_cm_out = (v(vop) + v(vom)) / 2.0
print i_supply p_diss v_cm_out v(vop) v(vom) v(VCMFB)

* 2. AC Analysis for Closed-Loop Gain and Bandwidth
ac dec 50 100k 10G
let vdiff_out = v(vop) - v(vom)
let vdiff_in = v(vip) - v(vim)
let gain_cl = vdiff_out / vdiff_in
let gain_cl_db = vdb(vop) - vdb(vom)
meas ac cl_gain_dc find gain_cl_db at=100k

* 3. Transient Analysis (Baker simulation 0 to 90ns)
tran 0.05n 90n
let v_out_diff = v(vop) - v(vom)
let v_in_diff = v(vip) - v(vim)
meas tran v_out_max max v_out_diff from=10n to=20n
meas tran v_out_min min v_out_diff from=20n to=30n
meas tran t_settle trig v_in_diff val=0.0 rise=1 targ v_out_diff val=-0.198 fall=1
print i_supply p_diss v_cm_out
quit
.endc
.end

